customCSS:
.t, .history { color: #6e738d; }
.join { color: #a6da95; }
.part, .quit { color: #6e738d; }
.kick, .error { color: #ed8796; }
.notice { color: #eed49f; }
.action { color: #c6a0f6; }
.mode, .nick, .topic, .server { color: #8bd5ca; }
.highlight { color: #cad3f5; background-color: #494d64; border-left: 3px solid #c6a0f6; padding-left: 8px; }
.reply { color: #6e738d; border-left: 2px solid #8aadf4; padding-left: 6px; }
.oper { color: #24273a; background-color: #eed49f; }
.reactions { color: #8aadf4; background-color: #363a4f; }
.card { background-color: #363a4f; border-color: #6e738d; }
.card-title { color: #8aadf4; }
.card-desc { color: #6e738d; }
.daychange { color: #6e738d; border-color: #363a4f; }
